package com.bankslotborders;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;

final class BankGridHighlights
{
 private BankGridHighlights() { }
 static void paint(Graphics2D g, BankGridLayout layout, BankSlotBordersConfig config,
  Point mouse, Point source)
 {
  Rectangle hovered = layout.cellAt(mouse);
  if (hovered != null)
  {
   if (config.rowGuide() || config.columnGuide())
   {
    Color color = config.guideColor();
    if (color != null) { g.setColor(color); g.fill(layout.guides(hovered,config.rowGuide(),config.columnGuide())); }
   }
   if (config.hoverHighlight()) fill(g,hovered,config.hoverColor());
  }
  if (config.sourceHighlight())
  {
   Rectangle original = layout.cellAt(source);
   if (original != null) fill(g,original,config.sourceColor());
  }
 }
 private static void fill(Graphics2D g, Rectangle cell, Color color)
 {
  if (color == null) return;
  g.setColor(color);
  g.fillRect(cell.x+2,cell.y+2,Math.max(1,cell.width-4),Math.max(1,cell.height-4));
 }
}

package com.bankslotborders;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.util.List;
import java.util.TreeSet;

// Optional features share the established painter's geometry without changing it.
final class BankGridLayout
{
 private final Rectangle viewport;
 private final int firstX, dx, dy;
 private final TreeSet<Integer> rows;

 BankGridLayout(Rectangle viewport, List<Rectangle> items)
 {
  this.viewport = new Rectangle(viewport);
  TreeSet<Integer> xs = new TreeSet<>(), ys = new TreeSet<>();
  for (Rectangle item : items) { xs.add(item.x); ys.add(item.y); }
  Rectangle sample = items.get(0);
  dx = BankGridPainter.pitch(xs,48,sample.width);
  dy = BankGridPainter.pitch(ys,36,sample.height);
  int origin = xs.first() - Math.max(0,dx-sample.width)/2;
  firstX = origin + Math.floorDiv(viewport.x-origin,dx)*dx;
  rows = BankGridPainter.rowTops(ys,dy,sample.height,viewport);
 }

 Rectangle cellAt(Point point)
 {
  if (point == null || !viewport.contains(point)) return null;
  Integer top = rows.floor(point.y);
  if (top == null || point.y >= top + dy) return null;
  int left = firstX + Math.floorDiv(point.x-firstX,dx)*dx;
  return new Rectangle(left,top,dx,dy);
 }

 Area rowArea()
 {
  Area result = new Area();
  for (int y : rows) result.add(new Area(new Rectangle(viewport.x,y,viewport.width,dy)));
  result.intersect(new Area(viewport));
  return result;
 }

 Area guides(Rectangle cell, boolean row, boolean column)
 {
  Area result = new Area();
  if (row) result.add(new Area(new Rectangle(viewport.x,cell.y,viewport.width,cell.height)));
  if (column) result.add(new Area(new Rectangle(cell.x,viewport.y,cell.width,viewport.height)));
  result.intersect(rowArea());
  return result;
 }
}

package com.bankslotborders;
import java.awt.*;
import java.awt.geom.Area;
import java.util.List;
import java.util.TreeSet;
final class BankGridPainter {
 private BankGridPainter() {}
 // Normal bank spacing is the fallback for a tab with only one item.
 static int pitch(TreeSet<Integer> positions,int fallback,int minimum) {
  Integer previous=null;
  int smallest=Integer.MAX_VALUE;
  for(int position:positions) {
   if(previous!=null && position-previous>=minimum) smallest=Math.min(smallest,position-previous);
   previous=position;
  }
  // A sparse layout may skip entire rows/columns; do not mistake that for
  // a larger cell. Small differences from real neighbors are authoritative.
  return smallest==Integer.MAX_VALUE || smallest>fallback*3/2 ? fallback : smallest;
 }
 static void paint(Graphics2D g,Rectangle viewport,List<Rectangle> items,Color color,int thickness,GridStyle style) {
  if(items.isEmpty() || color==null || color.getAlpha()==0) return;
  TreeSet<Integer> xs=new TreeSet<>(),ys=new TreeSet<>();
  for(Rectangle item:items) { xs.add(item.x); ys.add(item.y); }
  Rectangle sample=items.get(0);
  int dx=pitch(xs,48,sample.width),dy=pitch(ys,36,sample.height);
  int originX=xs.first()-Math.max(0,dx-sample.width)/2;
  int firstX=originX+Math.floorDiv(viewport.x-originX,dx)*dx;
  TreeSet<Integer> rowTops=rowTops(ys,dy,sample.height,viewport);
  int t=Math.max(1,Math.min(4,thickness));
  g.setColor(color);
  if(style==GridStyle.SHADED_SQUARES) {
   for(int y:rowTops)
    for(int x=firstX;x<viewport.x+viewport.width;x+=dx)
     g.fillRect(x+2,y+2,Math.max(1,dx-4),Math.max(1,dy-4));
  } else {
   // A union keeps intersections from receiving the alpha twice.
   Area lines=new Area();
   for(int x=firstX;x<viewport.x+viewport.width;x+=dx)
    lines.add(new Area(new Rectangle(x,viewport.y,t,viewport.height)));
   for(int y:rowTops) {
    lines.add(new Area(new Rectangle(viewport.x,y,viewport.width,t)));
    lines.add(new Area(new Rectangle(viewport.x,y+dy,viewport.width,t)));
   }
   g.fill(lines);
  }
 }
 // Bank tab headings introduce gaps that are not multiples of the slot pitch.
 // Anchor every occupied row independently, then fill whole empty rows between
 // anchors. Keep the heading remainder blank rather than shifting later rows.
 static TreeSet<Integer> rowTops(TreeSet<Integer> positions,int pitch,int itemHeight,Rectangle viewport) {
  TreeSet<Integer> tops=new TreeSet<>();
  int padding=Math.max(0,pitch-itemHeight)/2;
  Integer previous=null;
  for(int position:positions) {
   int top=position-padding;
   if(previous!=null) {
    for(int empty=previous+pitch;empty+pitch<=top;empty+=pitch) tops.add(empty);
   }
   tops.add(top);
   previous=top;
  }
  int first=tops.first(),last=tops.last();
  for(int y=first-pitch;y+pitch>viewport.y;y-=pitch) tops.add(y);
  for(int y=last+pitch;y<viewport.y+viewport.height;y+=pitch) tops.add(y);
  return tops;
 }
}

package com.bankslotborders;

import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;

final class BankGridRenderer
{
 private BankGridRenderer() { }
 static void paint(Graphics2D graphics, Rectangle viewport, List<Rectangle> items,
  BankSlotBordersConfig config, GridAppearance appearance, Point mouse, Point source)
 {
  if (items.isEmpty()) return;
  Graphics2D g = (Graphics2D) graphics.create();
  try
  {
   g.clip(viewport);
   boolean extras = config.hoverHighlight() || config.sourceHighlight() || config.rowGuide() || config.columnGuide();
   BankGridLayout layout = extras || config.respectSectionGaps() ? new BankGridLayout(viewport,items) : null;
   if (config.respectSectionGaps()) g.clip(layout.rowArea());
   // Extras go beneath the grid so original boundaries remain readable.
   if (extras) BankGridHighlights.paint(g,layout,config,mouse,source);
   if (appearance.style == GridStyle.ITEM_BORDERS)
   {
    for (Rectangle item : items) SlotBorderPainter.paint(g,item,appearance.color,appearance.thickness);
   }
   else BankGridPainter.paint(g,viewport,items,appearance.color,appearance.thickness,appearance.style);
  }
  finally { g.dispose(); }
 }
}

package com.bankslotborders;
